import { describe, expect, it } from "vitest";
import { roundCents } from "../src/billing/round";

describe("roundCents", () => {
  it("rounds exact half cents to the even cent so ties don't bias invoices upward", () => {
    expect(roundCents(0.5)).toBe(0);
    expect(roundCents(1.5)).toBe(2);
    expect(roundCents(2.5)).toBe(2);
    expect(roundCents(-2.5)).toBe(-2);
    expect(roundCents(-1.5)).toBe(-2);
  });

  it("rounds non-tie amounts to the nearest cent", () => {
    expect(roundCents(2.4)).toBe(2);
    expect(roundCents(2.6)).toBe(3);
    expect(roundCents(-2.6)).toBe(-3);
    expect(roundCents(100)).toBe(100);
  });

  it("treats float-noise ties as ties", () => {
    // 0.1 + 0.2 + 2.2 = 2.5000000000000004 in IEEE 754
    expect(roundCents(0.1 + 0.2 + 2.2)).toBe(2);
  });
});

